INSERT INTO public.schools (source_ref,name,education_level,province_old,district_old,address_text,maps_search_url,source_url,verification_note,address_detail_level,source_batch,gps_verified)
SELECT x.source_ref,x.name,x.education_level,x.province_old,x.district_old,x.address_text,x.maps_search_url,x.source_url,x.verification_note,x.address_detail_level,'2026-11-21-ca-mau-hau-giang-old-gap-audit-01',FALSE FROM incoming x
WHERE NOT (EXISTS (SELECT 1 FROM public.schools s WHERE s.province_old=x.province_old AND s.district_old=x.district_old AND lower(regexp_replace(btrim(s.name),'[^[:alnum:]]','','g'))=lower(regexp_replace(btrim(x.name),'[^[:alnum:]]','','g'))))
ON CONFLICT (source_ref) DO NOTHING;
COMMIT;
